impl AntiRejectViaHorizonFrom<MultiVector> for Horizon {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div      pow
    //      f32        4       13        0        0
    //    simd2        0        1        0      N/A
    //    simd3        4       12        0      N/A
    //    simd4        0        4        0      N/A
    // Totals...
    // yes simd        8       30        0      N/A
    //  no simd       16       67        0        0
    fn anti_reject_via_horizon_from(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        let wedge_g0_y = self[e3215] * other[e4];
        let wedge_g10 = self[e3215] * other[scalar];
        let right_dual_g0 = other.group0().yx() * Simd32x2::from([-1.0, 1.0]);
        let right_dual_g1 = other.group9().yzwx() * Simd32x4::from([-1.0, -1.0, -1.0, 1.0]);
        let right_dual_g3 = other.group7().with_w(other[e321] * -1.0);
        let right_dual_g6_xyz = other.group5() * Simd32x3::from(-1.0);
        let right_dual_g7 = other.group3().xyz() * Simd32x3::from(-1.0);
        let right_dual_g9 = other.group1().wxyz() * Simd32x4::from([-1.0, 1.0, 1.0, 1.0]);
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([(wedge_g0_y * right_dual_g0[0]) + (wedge_g10 * right_dual_g1[3]), wedge_g0_y * right_dual_g0[1]]),
            // e1, e2, e3, e4
            ((Simd32x3::from(wedge_g0_y) * right_dual_g1.xyz()) - (Simd32x3::from(wedge_g10) * right_dual_g3.xyz())).with_w(wedge_g0_y * right_dual_g1[3]),
            // e5
            (wedge_g0_y * other[e3215]) - (wedge_g10 * right_dual_g3[3]),
            // e41, e42, e43, e45
            right_dual_g3 * Simd32x4::from(wedge_g0_y),
            // e15, e25, e35
            (right_dual_g6_xyz * Simd32x3::from(wedge_g10)) + (Simd32x3::from(wedge_g0_y) * other.group8()),
            // e23, e31, e12
            (right_dual_g7 * Simd32x3::from(wedge_g10)) + (Simd32x3::from(wedge_g0_y) * other.group6().xyz()),
            // e415, e425, e435, e321
            (right_dual_g6_xyz * Simd32x3::from(wedge_g0_y)).with_w((wedge_g0_y * other[e45]) - (wedge_g10 * right_dual_g9[0])),
            // e423, e431, e412
            right_dual_g7 * Simd32x3::from(wedge_g0_y),
            // e235, e315, e125
            -(Simd32x3::from(wedge_g0_y) * other.group4()) - (Simd32x3::from(wedge_g10) * right_dual_g9.yzw()),
            // e1234, e4235, e4315, e4125
            right_dual_g9 * Simd32x4::from(wedge_g0_y),
            // e3215
            (wedge_g10 * right_dual_g0[1]) - (wedge_g0_y * other[e5]),
        )
    }
}
